1	import { Client, type ClientChannel } from "ssh2";
2	
3	/**
4	 * READ-ONLY source auto-detection for the migration wizard.
5	 *
6	 * Given SSH credentials for a customer-specified SOURCE box, we open a single
7	 * password-authenticated SSH session and *look* at what is there — web roots,
8	 * home directories and database engines — so the wizard can present a
9	 * pre-checked "here's what we found" checklist instead of making the customer
10	 * type paths and DB names by hand.
11	 *
12	 * SECURITY — the source is UNTRUSTED and customer-supplied, so this mirrors the
13	 * hardening in worker/migrate-real.ts:
14	 *
15	 *   1. The scan is strictly READ-ONLY. Every probe is a fixed, input-free shell
16	 *      script (directory globs are expanded by the REMOTE shell from constant
17	 *      patterns — no customer value is ever interpolated into it). We never
18	 *      write, install or modify anything on the source. Database listing reads
19	 *      its credentials file from `/dev/stdin`, so not even a temp file is
20	 *      written to the source.
21	 *
22	 *   2. SECRETS NEVER TOUCH A COMMAND STRING. The SSH password is handed to the
23	 *      ssh2 transport, never a shell. DB credentials are streamed into the far
24	 *      command's STDIN (a `[client]` defaults file / a `.pgpass` line consumed
25	 *      via `/dev/stdin`), never as an argv token.
26	 *
27	 *   3. STRICT ALLOWLIST VALIDATION. Host / port / SSH user / DB user are checked
28	 *      against shell-inert allowlists before use — we reject, never sanitize.
29	 *      Paths and DB names that come BACK from the source are re-validated against
30	 *      the same allowlist the real engine enforces; anything that doesn't match
31	 *      is dropped (it could not be migrated safely anyway).
32	 *
33	 *   4. Everything is timeout-bounded and size/count-capped.
34	 */
35	
36	// ---- Result shapes (no secrets ever) --------------------------------------
37	export type WebAppType = "wordpress" | "laravel" | "django" | "node" | "php" | "unknown";
38	
39	export type DetectedWebRoot = { path: string; sizeLabel: string; appType: WebAppType };
40	export type DetectedHome = { path: string; sizeLabel: string };
41	export type DetectedDatabase = { engine: "mysql" | "postgres"; name: string; sizeLabel: string };
42	export type DetectedEngine = {
43	  engine: "mysql" | "postgres";
44	  present: boolean;
45	  listening: boolean;
46	  listed: boolean; // did we successfully enumerate databases with the given creds?
47	};
48	
49	export type ScanResult = {
50	  ok: boolean;
51	  webRoots: DetectedWebRoot[];
52	  homes: DetectedHome[];
53	  databases: DetectedDatabase[];
54	  engines: DetectedEngine[];
55	  notes: string[];
56	  synthetic?: boolean;
57	};
58	
59	export type DetectInput = {
60	  host: string;
61	  port: number;
62	  user: string;
63	  password: string;
64	  /** Optional DB admin creds — only then can we enumerate database names/sizes. */
65	  dbUser?: string;
66	  dbPassword?: string;
67	};
68	
69	// ---- Timeouts / caps ------------------------------------------------------
70	const CONNECT_TIMEOUT_MS = 20_000;
71	const SCAN_TIMEOUT_MS = 75_000; // the big du/probe sweep
72	const DB_TIMEOUT_MS = 25_000;
73	const MAX_WEB_ROOTS = 40;
74	const MAX_HOMES = 40;
75	const MAX_DATABASES = 60;
76	
77	// ---- Strict allowlist validators (mirror worker/migrate-real.ts) ----------
78	const HOSTNAME_RE = /^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$/;
79	const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
80	const IPV6_RE = /^[0-9A-Fa-f:]{2,45}$/;
81	const USER_RE = /^[a-z_][a-z0-9_-]{0,31}$/;
82	const DBUSER_RE = /^[A-Za-z0-9_]{1,64}$/;
83	const PATH_RE = /^\/[A-Za-z0-9._/-]{0,255}$/;
84	// MUST match IDENT_RE in worker/migrate-real.ts — only surface DB names the real
85	// transfer engine can actually migrate, so nothing selected here fails later.
86	const DBNAME_RE = /^[A-Za-z0-9_]{1,64}$/;
87	
88	function assert(cond: unknown, msg: string): asserts cond {
89	  if (!cond) throw new Error(msg);
90	}
91	function validHost(h: string): boolean {
92	  return typeof h === "string" && (HOSTNAME_RE.test(h) || IPV4_RE.test(h) || IPV6_RE.test(h));
93	}
94	function validPath(p: string): boolean {
95	  return typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//");
96	}
97	
98	/** Collapse duplicate slashes and strip a trailing slash from a du-emitted path. */
99	function normalizeRemotePath(p: string): string {
100	  const collapsed = (p ?? "").replace(/\/{2,}/g, "/").replace(/\/+$/, "");
101	  return collapsed || "/";
102	}
103	
104	// ---- SSH plumbing (same shape as migrate-real.ts) -------------------------
105	function execRemote(
106	  conn: Client,
107	  cmd: string,
108	  timeoutMs: number
109	): Promise<{ code: number; stdout: string; stderr: string }> {
110	  return new Promise((resolve, reject) => {
111	    conn.exec(cmd, (err, stream: ClientChannel) => {
112	      if (err) return reject(err);
113	      let stdout = "";
114	      let stderr = "";
115	      const timer = setTimeout(() => {
116	        try {
117	          stream.close();
118	        } catch {
119	          /* ignore */
120	        }
121	        reject(new Error("remote command timed out"));
122	      }, timeoutMs);
123	      stream
124	        .on("close", (code: number) => {
125	          clearTimeout(timer);
126	          resolve({ code: code ?? 0, stdout, stderr });
127	        })
128	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
129	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
130	    });
131	  });
132	}
133	
134	/** Run a command, streaming `input` into its STDIN (secret goes here, never argv). */
135	function execRemoteInput(
136	  conn: Client,
137	  cmd: string,
138	  input: string,
139	  timeoutMs: number
140	): Promise<{ code: number; stdout: string; stderr: string }> {
141	  return new Promise((resolve, reject) => {
142	    conn.exec(cmd, (err, stream: ClientChannel) => {
143	      if (err) return reject(err);
144	      let stdout = "";
145	      let stderr = "";
146	      const timer = setTimeout(() => {
147	        try {
148	          stream.close();
149	        } catch {
150	          /* ignore */
151	        }
152	        reject(new Error("remote command timed out"));
153	      }, timeoutMs);
154	      stream
155	        .on("close", (code: number) => {
156	          clearTimeout(timer);
157	          resolve({ code: code ?? 0, stdout, stderr });
158	        })
159	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
160	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
161	      stream.end(input);
162	    });
163	  });
164	}
165	
166	function connectSource(input: DetectInput): Promise<Client> {
167	  return new Promise((resolve, reject) => {
168	    const conn = new Client();
169	    conn.on("ready", () => resolve(conn));
170	    conn.on("error", (e) => reject(e instanceof Error ? e : new Error(String(e))));
171	    conn.connect({
172	      host: input.host,
173	      port: input.port,
174	      username: input.user,
175	      password: input.password,
176	      readyTimeout: CONNECT_TIMEOUT_MS,
177	      // Password-only: never offer a local key to the untrusted source host.
178	      tryKeyboard: false,
179	    });
180	  });
181	}
182	
183	// ---- Helpers --------------------------------------------------------------
184	function humanBytes(n: number): string {
185	  if (!Number.isFinite(n) || n <= 0) return "0 B";
186	  const units = ["B", "KB", "MB", "GB", "TB"];
187	  let i = 0;
188	  let v = n;
189	  while (v >= 1024 && i < units.length - 1) {
190	    v /= 1024;
191	    i++;
192	  }
193	  return `${v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)} ${units[i]}`;
194	}
195	
196	/**
197	 * The read-only probe script. Deliberately input-free: the only variable parts
198	 * are constant shell globs expanded by the REMOTE shell, so there is no
199	 * injection surface. POSIX-sh only (works under `sh` or `bash`).
200	 */
201	// NOTE: authored as a plain string (not a template literal) so shell `${...}`
202	// parameter expansions can never collide with JS `${}` interpolation. Any
203	// trailing/duplicate slashes in emitted paths are normalized in JS below.
204	const SCAN_SCRIPT = [
205	  "export LC_ALL=C",
206	  'if command -v timeout >/dev/null 2>&1; then TO="timeout 25"; else TO=""; fi',
207	  "emit_web() {",
208	  "  d=$1",
209	  '  [ -d "$d" ] || return 0',
210	  '  sz=$($TO du -shx "$d" 2>/dev/null | cut -f1)',
211	  '  [ -n "$sz" ] || sz=\'?\'',
212	  "  t=unknown",
213	  '  if [ -f "$d/wp-config.php" ]; then t=wordpress',
214	  '  elif [ -f "$d/artisan" ]; then t=laravel',
215	  '  elif [ -f "$d/manage.py" ]; then t=django',
216	  '  elif [ -f "$d/package.json" ]; then t=node',
217	  '  elif [ -f "$d/composer.json" ]; then t=php',
218	  "  else",
219	  '    for f in "$d"/*.php; do [ -e "$f" ] && { t=php; break; }; done',
220	  "  fi",
221	  "  printf 'WEB\\t%s\\t%s\\t%s\\n' \"$t\" \"$sz\" \"$d\"",
222	  "}",
223	  'for d in /var/www/html /usr/share/nginx/html /var/www /srv/www; do emit_web "$d"; done',
224	  'for d in /var/www/*/ /srv/www/*/ /home/*/public_html; do emit_web "$d"; done',
225	  "for d in /home/*/; do",
226	  '  [ -d "$d" ] || continue',
227	  '  sz=$($TO du -shx "$d" 2>/dev/null | cut -f1); [ -n "$sz" ] || sz=\'?\'',
228	  "  printf 'HOME\\t%s\\t%s\\n' \"$sz\" \"$d\"",
229	  "done",
230	  "if [ -d /root ]; then",
231	  "  sz=$($TO du -shx /root 2>/dev/null | cut -f1); [ -n \"$sz\" ] || sz='?'",
232	  "  printf 'HOME\\t%s\\t%s\\n' \"$sz\" /root",
233	  "fi",
234	  "mp=0; ml=0; pp=0; pl=0",
235	  "{ command -v mysqld >/dev/null 2>&1 || command -v mariadbd >/dev/null 2>&1 || command -v mysql >/dev/null 2>&1 || [ -d /var/lib/mysql ]; } && mp=1",
236	  "{ command -v pg_dump >/dev/null 2>&1 || command -v psql >/dev/null 2>&1 || [ -d /var/lib/postgresql ]; } && pp=1",
237	  "ports=$( (ss -H -lnt 2>/dev/null || netstat -lnt 2>/dev/null) )",
238	  "printf '%s\\n' \"$ports\" | grep -q ':3306[^0-9]' && ml=1",
239	  "printf '%s\\n' \"$ports\" | grep -q ':5432[^0-9]' && pl=1",
240	  "printf 'ENGINE\\tmysql\\t%s\\t%s\\n' \"$mp\" \"$ml\"",
241	  "printf 'ENGINE\\tpostgres\\t%s\\t%s\\n' \"$pp\" \"$pl\"",
242	].join("\n");
243	
244	const SYSTEM_SCHEMAS = new Set(["information_schema", "performance_schema", "mysql", "sys"]);
245	
246	/** Parse a `du -sh`-style size label ("1.2G", "340M", "512K") into bytes for sorting. */
247	function parseSizeLabel(label: string): number {
248	  const m = /^([\d.]+)\s*([KMGT]?)/i.exec(label.trim());
249	  if (!m) return 0;
250	  const n = parseFloat(m[1]);
251	  const mult: Record<string, number> = { "": 1, K: 1024, M: 1024 ** 2, G: 1024 ** 3, T: 1024 ** 4 };
252	  return n * (mult[m[2].toUpperCase()] ?? 1);
253	}
254	
255	// ---- Public entrypoint ----------------------------------------------------
256	/**
257	 * SSH into the source (read-only) and return a structured inventory. Throws only
258	 * on a fatal connection/auth failure; a source that is reachable but has (say) no
259	 * readable DB creds still returns a useful partial result with notes.
260	 */
261	export async function detectSource(input: DetectInput): Promise<ScanResult> {
262	  assert(validHost(input.host), "source host is not a valid hostname or IP address");
263	  assert(Number.isInteger(input.port) && input.port >= 1 && input.port <= 65535, "source SSH port is out of range");
264	  assert(USER_RE.test(input.user), "source SSH username contains unsupported characters");
265	  assert(input.password && input.password.length > 0, "source SSH password is required");
266	
267	  const notes: string[] = [];
268	  const webRoots: DetectedWebRoot[] = [];
269	  const homes: DetectedHome[] = [];
270	  const databases: DetectedDatabase[] = [];
271	  const engines: DetectedEngine[] = [];
272	
273	  const conn = await connectSource(input);
274	  try {
275	    // ---- 1. Filesystem + engine probe (fixed, input-free, read-only) ------
276	    const scan = await execRemote(conn, SCAN_SCRIPT, SCAN_TIMEOUT_MS);
277	    const engineState: Record<"mysql" | "postgres", { present: boolean; listening: boolean }> = {
278	      mysql: { present: false, listening: false },
279	      postgres: { present: false, listening: false },
280	    };
281	
282	    for (const raw of scan.stdout.split("\n")) {
283	      const line = raw.replace(/\r$/, "");
284	      if (!line) continue;
285	      const parts = line.split("\t");
286	      if (parts[0] === "WEB" && parts.length >= 4) {
287	        const appType = parts[1] as WebAppType;
288	        const sizeLabel = parts[2] || "?";
289	        const path = normalizeRemotePath(parts[3]);
290	        if (!validPath(path)) continue;
291	        if (webRoots.some((w) => w.path === path)) continue;
292	        webRoots.push({
293	          path,
294	          sizeLabel,
295	          appType: (["wordpress", "laravel", "django", "node", "php"] as WebAppType[]).includes(appType)
296	            ? appType
297	            : "unknown",
298	        });
299	      } else if (parts[0] === "HOME" && parts.length >= 3) {
300	        const sizeLabel = parts[1] || "?";
301	        const path = normalizeRemotePath(parts[2]);
302	        if (!validPath(path)) continue;
303	        if (homes.some((h) => h.path === path)) continue;
304	        homes.push({ path, sizeLabel });
305	      } else if (parts[0] === "ENGINE" && parts.length >= 4) {
306	        const eng = parts[1] === "postgres" ? "postgres" : "mysql";
307	        engineState[eng] = { present: parts[2] === "1", listening: parts[3] === "1" };
308	      }
309	    }
310	
311	    // Prune web roots that are ancestors of another detected root (avoid copying
312	    // a parent AND its children — e.g. drop /var/www when /var/www/html exists).
313	    const pruned = webRoots.filter(
314	      (a) => !webRoots.some((b) => b.path !== a.path && b.path.startsWith(a.path + "/"))
315	    );
316	    webRoots.length = 0;
317	    webRoots.push(...pruned.slice(0, MAX_WEB_ROOTS));
318	    homes.splice(MAX_HOMES);
319	
320	    // ---- 2. Databases — only if the customer supplied DB creds ------------
321	    const hasSafePass =
322	      !!input.dbPassword && !input.dbPassword.includes("\n") && !input.dbPassword.includes("\r");
323	    if (input.dbPassword && !hasSafePass) {
324	      notes.push("Database password contains unsupported characters — databases were skipped.");
325	    }
326	
327	    for (const eng of ["mysql", "postgres"] as const) {
328	      const st = engineState[eng];
329	      const rec: DetectedEngine = { engine: eng, present: st.present, listening: st.listening, listed: false };
330	      if (st.present && hasSafePass) {
331	        const effUser = (input.dbUser && input.dbUser.trim()) || (eng === "mysql" ? "root" : "postgres");
332	        if (!DBUSER_RE.test(effUser)) {
333	          notes.push(`Database user "${effUser}" has unsupported characters — ${eng} databases were skipped.`);
334	        } else {
335	          try {
336	            const found =
337	              eng === "mysql"
338	                ? await listMysql(conn, effUser, input.dbPassword!)
339	                : await listPostgres(conn, effUser, input.dbPassword!);
340	            for (const d of found) {
341	              if (databases.length >= MAX_DATABASES) break;
342	              databases.push(d);
343	            }
344	            rec.listed = true;
345	          } catch (e: any) {
346	            notes.push(
347	              `${eng === "mysql" ? "MySQL" : "PostgreSQL"} is installed but we couldn't read its databases with those credentials — you can add databases manually.`
348	            );
349	          }
350	        }
351	      } else if (st.present && !input.dbPassword) {
352	        notes.push(
353	          `${eng === "mysql" ? "MySQL" : "PostgreSQL"} detected — add a database password to include databases in the migration.`
354	        );
355	      }
356	      engines.push(rec);
357	    }
358	
359	    databases.sort((a, b) => parseSizeLabel(b.sizeLabel) - parseSizeLabel(a.sizeLabel));
360	
361	    return { ok: true, webRoots, homes, databases, engines, notes };
362	  } finally {
363	    try {
364	      conn.end();
365	    } catch {
366	      /* best-effort */
367	    }
368	  }
369	}
370	
371	/** Enumerate MySQL/MariaDB schemas + sizes. Creds read from /dev/stdin (never argv). */
372	async function listMysql(conn: Client, user: string, pass: string): Promise<DetectedDatabase[]> {
373	  // `--defaults-extra-file=/dev/stdin` makes mysql read the [client] block from
374	  // the STDIN we stream below — the password never appears on the command line.
375	  const query =
376	    "SELECT table_schema, IFNULL(SUM(data_length+index_length),0) " +
377	    "FROM information_schema.tables GROUP BY table_schema;";
378	  const cnf = `[client]\nuser=${user}\npassword=${pass}\nhost=127.0.0.1\nprotocol=tcp\n`;
379	  const r = await execRemoteInput(
380	    conn,
381	    `mysql --defaults-extra-file=/dev/stdin -N -B -e ${shSingleQuote(query)}`,
382	    cnf,
383	    DB_TIMEOUT_MS
384	  );
385	  if (r.code !== 0) throw new Error(r.stderr.slice(0, 200) || `mysql exit ${r.code}`);
386	  const out: DetectedDatabase[] = [];
387	  for (const line of r.stdout.split("\n")) {
388	    const [name, bytes] = line.replace(/\r$/, "").split("\t");
389	    if (!name || SYSTEM_SCHEMAS.has(name.toLowerCase())) continue;
390	    if (!DBNAME_RE.test(name)) continue;
391	    out.push({ engine: "mysql", name, sizeLabel: humanBytes(Number(bytes) || 0) });
392	  }
393	  return out;
394	}
395	
396	/** Enumerate PostgreSQL databases + sizes. Creds read from /dev/stdin (.pgpass). */
397	async function listPostgres(conn: Client, user: string, pass: string): Promise<DetectedDatabase[]> {
398	  const query =
399	    "SELECT datname, pg_database_size(datname) FROM pg_database WHERE datistemplate = false;";
400	  const pgpass = `127.0.0.1:5432:*:${user}:${pass}\n`;
401	  const r = await execRemoteInput(
402	    conn,
403	    `PGPASSFILE=/dev/stdin psql -h 127.0.0.1 -U ${user} -w -A -t -F '\t' -c ${shSingleQuote(query)}`,
404	    pgpass,
405	    DB_TIMEOUT_MS
406	  );
407	  if (r.code !== 0) throw new Error(r.stderr.slice(0, 200) || `psql exit ${r.code}`);
408	  const out: DetectedDatabase[] = [];
409	  for (const line of r.stdout.split("\n")) {
410	    const [name, bytes] = line.replace(/\r$/, "").split("\t");
411	    if (!name || name === "postgres") continue;
412	    if (!DBNAME_RE.test(name)) continue;
413	    out.push({ engine: "postgres", name, sizeLabel: humanBytes(Number(bytes) || 0) });
414	  }
415	  return out;
416	}
417	
418	/**
419	 * Single-quote a FIXED, code-authored SQL string for the remote shell. The
420	 * inputs here are compile-time constants (never customer data), so this only
421	 * guards the literal `'` inside our own query text.
422	 */
423	function shSingleQuote(s: string): string {
424	  return `'${s.replace(/'/g, `'\\''`)}'`;
425	}
426	
427	// ---- Synthetic results for SANDBOX / staging ------------------------------
428	/**
429	 * Realistic fake inventory so the wizard works end-to-end on staging without
430	 * ever opening a real SSH connection. Mirrors the real shape exactly.
431	 */
432	export function syntheticScan(input: Pick<DetectInput, "dbPassword">): ScanResult {
433	  const withDbs = !!input.dbPassword;
434	  const notes: string[] = [];
435	  if (!withDbs) notes.push("MySQL detected — add a database password to include databases in the migration.");
436	  return {
437	    ok: true,
438	    synthetic: true,
439	    webRoots: [
440	      { path: "/var/www/html", sizeLabel: "1.2 GB", appType: "wordpress" },
441	      { path: "/home/deploy/public_html", sizeLabel: "340 MB", appType: "laravel" },
442	      { path: "/srv/www/api", sizeLabel: "88 MB", appType: "node" },
443	    ],
444	    homes: [
445	      { path: "/home/deploy", sizeLabel: "1.4 GB" },
446	      { path: "/home/alice", sizeLabel: "210 MB" },
447	      { path: "/root", sizeLabel: "120 MB" },
448	    ],
449	    databases: withDbs
450	      ? [
451	          { engine: "mysql", name: "wordpress", sizeLabel: "220 MB" },
452	          { engine: "mysql", name: "shop", sizeLabel: "95 MB" },
453	          { engine: "postgres", name: "appdb", sizeLabel: "60 MB" },
454	        ]
455	      : [],
456	    engines: [
457	      { engine: "mysql", present: true, listening: true, listed: withDbs },
458	      { engine: "postgres", present: true, listening: true, listed: withDbs },
459	    ],
460	    notes,
461	  };
462	}
