81	// ---- Validation -------------------------------------------------------------
82	
83	// Hostname/FQDN (RFC-1123-ish) or IPv4 literal. Deliberately permissive on IPv6
84	// (a bracketed/colon form is accepted) — the worker's SSH layer does the final
85	// resolution; this only rejects obvious junk before we store anything.
86	const HOST_RE =
87	  /^(?:(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)*[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?|\d{1,3}(?:\.\d{1,3}){3}|\[?[0-9a-fA-F:]+\]?)$/;
88	const DEFAULT_PATHS = ["/var/www", "/home"];
89	const MAX_PATHS = 40;
90	const MAX_DATABASES = 25;
91	
92	function cleanPaths(paths: string[] | undefined): string[] {
93	  const list = (paths && paths.length ? paths : DEFAULT_PATHS)
94	    .map((p) => p.trim())
95	    .filter((p) => p.length > 0 && p.startsWith("/") && !p.includes("\0"));
96	  // De-dupe while preserving order.
97	  return [...new Set(list)].slice(0, MAX_PATHS);
98	}
