100	async function ownedTargetServer(serverId: string) {
101	  const user = await requireUser();
102	  const server = await db.server.findUnique({ where: { id: serverId } });
103	  if (!server) throw new Error("Not found");
104	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
105	  return { user, server };
106	}
