108	function toRow(
109	  m: {
110	    id: string;
111	    serverId: string;
112	    sourceHost: string;
113	    sourcePort: number;
114	    sourceUser: string;
115	    items: unknown;
116	    status: string;
117	    progress: number;
118	    step: string | null;
119	    log: string | null;
120	    lastError: string | null;
121	    createdAt: Date;
122	    finishedAt: Date | null;
123	  },
124	  server: { hostname: string; label: string | null } | null
125	): MigrationRow {
126	  const items = (m.items ?? {}) as {
127	    paths?: string[];
128	    databases?: { engine?: string; name?: string; user?: string }[];
129	  };
130	  return {
131	    id: m.id,
132	    serverId: m.serverId,
133	    // Migration has no Prisma relation to Server (serverId is a plain FK), so the
134	    // caller resolves the server row and passes it in.
135	    serverName: server ? server.label || server.hostname : null,
136	    sourceHost: m.sourceHost,
137	    sourcePort: m.sourcePort,
138	    sourceUser: m.sourceUser,
139	    paths: Array.isArray(items.paths) ? items.paths : [],
140	    // Strip every DB secret (passEnc) — expose only non-sensitive fields.
141	    databases: Array.isArray(items.databases)
142	      ? items.databases.map((d) => ({
143	          engine: String(d.engine ?? ""),
144	          name: String(d.name ?? ""),
145	          user: String(d.user ?? ""),
146	        }))
147	      : [],
148	    status: m.status,
149	    progress: m.progress,
150	    step: m.step,
151	    log: m.log,
152	    lastError: m.lastError,
153	    createdAt: m.createdAt.toISOString(),
154	    finishedAt: m.finishedAt ? m.finishedAt.toISOString() : null,
155	  };
