160	/**
161	 * Start a migration onto one of the caller's Nxeon servers. Verifies TARGET
162	 * ownership, validates the source connection details, encrypts every source
163	 * secret, writes the Migration row (PENDING) and enqueues a MIGRATE job. Returns
164	 * the new migration id; never returns any secret.
165	 */
166	export async function createMigration(
167	  input: CreateMigrationInput
168	): Promise<{ error?: string; id?: string }> {
169	  const { user, server } = await ownedTargetServer(input.serverId);
170	
171	  // Rate-limit: a few migrations per user per 10 minutes is plenty and stops
172	  // credential-stuffing the wizard against arbitrary source hosts.
173	  const rl = checkRateLimit(`migrate:create:${user.id}`, { max: 5, windowMs: 10 * 60 * 1000 });
174	  if (!rl.ok) {
175	    return { error: `Too many migrations started — please wait ${rl.retryAfterSec}s and try again.` };
176	  }
177	
178	  const host = (input.sourceHost ?? "").trim();
179	  if (!host || host.length > 253 || !HOST_RE.test(host)) {
180	    return { error: "Enter a valid source host — an IP address or domain name." };
181	  }
182	
183	  const port = input.sourcePort ?? 22;
184	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
185	    return { error: "SSH port must be between 1 and 65535." };
186	  }
187	
188	  const sourceUser = (input.sourceUser ?? "root").trim();
189	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
190	    return { error: "Enter the SSH username on the source server." };
191	  }
192	
193	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
194	    return { error: "Enter the SSH password for the source server." };
195	  }
196	
197	  const paths = cleanPaths(input.paths);
198	
199	  // Validate + encrypt each database. Passwords go straight into passEnc; the
200	  // plaintext never lands in the row.
201	  const databases: { engine: string; name: string; user: string; passEnc: string }[] = [];
202	  for (const d of input.databases ?? []) {
203	    if (databases.length >= MAX_DATABASES) break;
204	    const engine = d.engine;
205	    if (engine !== "mysql" && engine !== "postgres") {
206	      return { error: "Database engine must be MySQL or PostgreSQL." };
207	    }
208	    const name = (d.name ?? "").trim();
209	    const dbUser = (d.user ?? "").trim();
210	    if (!name || name.length > 128) return { error: "Enter a valid database name." };
211	    if (!dbUser || dbUser.length > 128) return { error: "Enter a valid database user." };
212	    databases.push({
213	      engine,
214	      name,
215	      user: dbUser,
216	      passEnc: encryptSecret(d.password ?? ""),
217	    });
218	  }
219	
220	  // Persist the (secret-free) detection snapshot alongside the chosen items so the
221	  // migration is traceable back to what auto-detection found. Reusing items.scan
222	  // avoids a schema change (Migration.items is a Json column).
223	  const scanSnapshot =
224	    input.scan && input.scan.ok
225	      ? {
226	          webRoots: input.scan.webRoots?.slice(0, 40) ?? [],
227	          homes: input.scan.homes?.slice(0, 40) ?? [],
228	          databases: input.scan.databases?.slice(0, 60) ?? [],
229	          engines: input.scan.engines ?? [],
230	          synthetic: !!input.scan.synthetic,
231	        }
232	      : undefined;
233	
234	  const migration = await db.migration.create({
235	    data: {
236	      userId: user.id,
237	      serverId: server.id,
238	      sourceHost: host,
239	      sourcePort: port,
240	      sourceUser,
241	      sourcePasswordEnc: encryptSecret(input.sourcePassword),
242	      items: scanSnapshot ? { paths, databases, scan: scanSnapshot } : { paths, databases },
243	      status: "PENDING",
244	      progress: 0,
245	      step: "Queued",
246	    },
247	  });
248	
249	  // Enqueue the worker job. serverId ties the job to the target (cascade delete +
250	  // traceability); the handler loads everything else from payload.migrationId.
251	  await db.job.create({
252	    data: {
253	      type: "MIGRATE",
254	      serverId: server.id,
255	      payload: { migrationId: migration.id },
256	    },
257	  });
258	
259	  await db.auditLog.create({
260	    data: {
261	      userId: user.id,
262	      action: "migration.create",
263	      detail: `${migration.id} ${sourceUser}@${host}:${port} -> ${server.hostname} (${paths.length} paths, ${databases.length} dbs)`,
264	    },
265	  });
266	
267	  revalidatePath("/dashboard/migrate");
268	  return { id: migration.id };
269	}
