271	/**
272	 * READ-ONLY auto-detection of a source box for the beginner wizard. Verifies the
273	 * caller owns the TARGET server (authz + a stricter rate limit than create),
274	 * validates the source connection details, then SSHes into the source and
275	 * inventories web roots / home directories / databases — never writing anything
276	 * on the source and never persisting the supplied credentials.
277	 *
278	 * The plaintext SSH/DB passwords are used in-memory for this one call only and
279	 * are NOT stored anywhere; the client re-supplies them to createMigration once
280	 * the customer confirms what to move. Returns a secret-free ScanResult.
281	 *
282	 * In SANDBOX (staging) this returns realistic SYNTHETIC results and never opens
283	 * a real SSH connection, so staging stays fully self-contained.
284	 */
285	export async function scanSource(input: {
286	  serverId: string;
287	  sourceHost: string;
288	  sourcePort?: number;
289	  sourceUser?: string;
290	  sourcePassword: string;
291	  dbUser?: string;
292	  dbPassword?: string;
293	}): Promise<{ error?: string; scan?: ScanResult }> {
294	  const { user } = await ownedTargetServer(input.serverId);
295	
296	  // Scanning SSHes into an arbitrary customer-named host, so throttle it harder
297	  // than migration creation to stop the wizard being used to probe hosts.
298	  const rl = checkRateLimit(`migrate:scan:${user.id}`, { max: 8, windowMs: 10 * 60 * 1000 });
299	  if (!rl.ok) {
300	    return { error: `Too many scans — please wait ${rl.retryAfterSec}s and try again.` };
301	  }
302	
303	  const host = (input.sourceHost ?? "").trim();
304	  if (!host || host.length > 253 || !HOST_RE.test(host)) {
305	    return { error: "Enter a valid source host — an IP address or domain name." };
306	  }
307	  const port = input.sourcePort ?? 22;
308	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
309	    return { error: "SSH port must be between 1 and 65535." };
310	  }
311	  const sourceUser = (input.sourceUser ?? "root").trim();
312	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
313	    return { error: "Enter the SSH username on the source server." };
314	  }
315	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
316	    return { error: "Enter the SSH password for the source server." };
317	  }
318	
319	  await db.auditLog.create({
320	    data: { userId: user.id, action: "migration.scan", detail: `${sourceUser}@${host}:${port}` },
321	  }).catch(() => {});
322	
323	  // SANDBOX: never touch the outside world — hand back synthetic detection.
324	  if (SANDBOX) {
325	    return { scan: syntheticScan({ dbPassword: input.dbPassword }) };
326	  }
327	
328	  // Hard overall timeout so a slow/hostile source can't hang the request.
329	  const HARD_TIMEOUT_MS = 90_000;
330	  try {
331	    const scan = await Promise.race<ScanResult>([
332	      detectSource({
333	        host,
334	        port,
335	        user: sourceUser,
336	        password: input.sourcePassword,
337	        dbUser: input.dbUser?.trim() || undefined,
338	        dbPassword: input.dbPassword || undefined,
339	      }),
340	      new Promise<ScanResult>((_, reject) =>
341	        setTimeout(() => reject(new Error("Scan timed out — the source server took too long to respond.")), HARD_TIMEOUT_MS)
342	      ),
343	    ]);
344	    return { scan };
345	  } catch (e: any) {
346	    const msg = `${e?.message ?? e}`;
347	    // Map the common connection failures to friendly, non-leaky copy.
348	    if (/authentication|denied|password/i.test(msg)) {
349	      return { error: "Couldn't sign in to the source server — check the SSH username and password." };
350	    }
351	    if (/ECONNREFUSED|ETIMEDOUT|EHOSTUNREACH|ENOTFOUND|timed out|getaddrinfo/i.test(msg)) {
352	      return { error: "Couldn't reach the source server — check the host and SSH port." };
353	    }
354	    return { error: "We couldn't scan that server. Double-check the details and try again." };
355	  }
356	}
