358	/** The current user's migrations, newest first, WITHOUT any decrypted secrets. */
359	export async function listMigrations(): Promise<MigrationRow[]> {
360	  const user = await requireUser();
361	  const rows = await db.migration.findMany({
362	    where: { userId: user.id },
363	    orderBy: { createdAt: "desc" },
364	  });
365	  const serverIds = [...new Set(rows.map((r) => r.serverId))];
366	  const servers = await db.server.findMany({
367	    where: { id: { in: serverIds } },
368	    select: { id: true, hostname: true, label: true },
369	  });
370	  const byId = new Map(servers.map((s) => [s.id, s]));
371	  return rows.map((m) => toRow(m, byId.get(m.serverId) ?? null));
372	}
