121	  const [homeSel, setHomeSel] = useState<Set<string>>(new Set());
122	  const [dbSel, setDbSel] = useState<Set<string>>(new Set());
123	  const [customPaths, setCustomPaths] = useState<string[]>([]);
124	  const [newPath, setNewPath] = useState("");
