126	  const hostValid = /^[a-zA-Z0-9.\-:[\]]+$/.test(host.trim()) && host.trim().length > 0;
127	  const portNum = Number(port);
128	  const portValid = Number.isInteger(portNum) && portNum >= 1 && portNum <= 65535;
129	  const canScan = hostValid && portValid && user.trim().length > 0 && password.length > 0;
130	
131	  const dbKey = (engine: string, name: string) => `${engine}:${name}`;
