584	function MigrationProgress({ id, onDone }: { id: string; onDone: () => void }) {
585	  const [row, setRow] = useState<MigrationRow | null>(null);
586	  const [error, setError] = useState<string | null>(null);
587	
588	  useEffect(() => {
589	    let cancelled = false;
590	    let timer: ReturnType<typeof setTimeout>;
591	
592	    async function poll() {
593	      try {
594	        const m = await getMigration(id);
595	        if (cancelled) return;
596	        setRow(m);
597	        if (m && (m.status === "DONE" || m.status === "FAILED")) return; // stop polling
598	      } catch {
599	        if (!cancelled) setError("Lost connection while checking progress.");
600	      }
601	      if (!cancelled) timer = setTimeout(poll, 3000);
602	    }
603	    poll();
604	    return () => {
605	      cancelled = true;
606	      clearTimeout(timer);
607	    };
608	  }, [id]);
609	
610	  const progress = row?.progress ?? 0;
611	  const done = row?.status === "DONE";
612	  const failed = row?.status === "FAILED";
613	
614	  return (
615	    <div className="space-y-6">
616	      <div className="card">
617	        <div className="mb-4 flex items-center justify-between">
618	          <h2 className="font-semibold">Migration in progress</h2>
619	          {row && <StatusDot status={row.status} />}
620	        </div>
621	
622	        {error && <div className="mb-4 rounded-xl border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-sm text-amber-300">{error}</div>}
623	
624	        <div className="mb-2 flex items-center justify-between text-sm">
625	          <span className="text-slate-300">{row?.step ?? "Queued…"}</span>
626	          <span className="font-semibold">{progress}%</span>
627	        </div>
628	        <div className="h-2.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
629	          <div
630	            className={`h-full rounded-full transition-all duration-500 ${failed ? "bg-red-400" : done ? "bg-emerald-400" : "bg-brand-500"}`}
631	            style={{ width: `${progress}%` }}
632	          />
633	        </div>
634	
635	        {failed && row?.lastError && (
