export type DetectedWebRoot = { path: string; sizeLabel: string; appType: WebAppType };
export type DetectedHome = { path: string; sizeLabel: string };
export type DetectedDatabase = { engine: "mysql" | "postgres"; name: string; sizeLabel: string };
export type DetectedEngine = {
  engine: "mysql" | "postgres";
  present: boolean;
  listening: boolean;
  listed: boolean; // did we successfully enumerate databases with the given creds?
};

// The runtime that pointed us at a candidate app directory (or "unknown" when a
// directory scan found app signatures without a matching running process).
export type AppRuntime =
  | "node"
  | "python"
  | "java"
  | "ruby"
  | "php-fpm"
  | "pm2"
  | "next"
  | "dotnet"
  | "unknown";
// The on-disk signature that marks a directory as an app worth migrating.
export type AppDirSignature =
  | "wordpress"
  | "laravel"
  | "django"
  | "node"
  | "php"
  | "compose"
  | "python"
  | "git-repo"
  | "unknown";

/** A candidate app directory discovered OUTSIDE the standard web roots — either a
 *  running process's cwd (#3) or a signature-bearing dir under /opt, /srv, /app… (#4). */
export type DetectedAppDir = {
  path: string;
  sizeLabel: string;
  runtime: AppRuntime;
  signature: AppDirSignature;
};
/** A running Docker container. `mounts` are the bind-mount host paths (the data to
 *  migrate); named volumes appear here too but are not absolute paths. */
export type DetectedContainer = {
  name: string;
