  const portNum=Number(pm[1]);
  let proc=""; const ssm=/users:\(\(\"([^\"]+)\"/.exec(body);
  if(ssm)proc=ssm[1]; else {const nsm=/\s(\d+)\/([^\s]+)\s*$/.exec(body); if(nsm)proc=nsm[2];}
  const k=portNum+"/"+proc; if(seen.has(k))return; seen.add(k);
  out.push({port:portNum,proc,role:PORT_ROLES[portNum]||"other"});
});
rl.on("close",()=>{out.sort((a,b)=>a.port-b.port); console.log(JSON.stringify(out,null,0));});
